import React from 'react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer, Tooltip } from 'recharts';
import "./PreResult.css";
import ic from "../image/ic.png"

const PreResult = ({ result }) => {
  // result オブジェクトから percentage, message, answers を取得
  const { percentage, message, answers } = result;

  // 質問の回答を元にスコア計算
  const calculateScores = (answers) => {
    return [
      { name: "欲", score: answers.question1 === "yes" ? 3 : 2 },
      { name: "財産", score: answers.question2 === "no" ? 3 : 2 },
      { name: "遺言", score: answers.question3 === "yes" ? 3 : 2 },
      { name: "手続", score: answers.question4 === "yes" ? 3 : 2 },
    ];
  };

  const radarData = calculateScores(answers);

  return (
    <div className="result-container">
      {/* 結果 */}
      <h1 className="result-title">
      <img src={ic} alt="ic" className="ic_logo" />診断結果
      </h1>

      <p className="result-text">
        あなたの家族がもめる確率は <span className="highlight">{percentage}%</span> です。
      </p>
      
      {/* レーダーチャート */}
      <div className="chart-container">
        <ResponsiveContainer width="100%" height="100%">
          <RadarChart cx="50%" cy="50%" outerRadius="85%" data={radarData}>
            <PolarGrid />
            <PolarAngleAxis 
              dataKey="name"
              tick={{ className: "polar-angle-axis-tick", dy: 5 }} 
            />
            <PolarRadiusAxis 
              domain={[0, 3]} 
              tick={{ className: "polar-radius-axis-tick", angle: 1 }} 
              tickCount={4} 
            />
            <Tooltip />
            <Radar name="診断結果" dataKey="score" stroke="#1E899D" fill="#1E899D" fillOpacity={0.6} />
          </RadarChart>
        </ResponsiveContainer>
      </div>
      
      {/* メッセージ部分 */}
      <div className="result-text">
        {message.map((line, index) => (
          <p key={index}>{line}</p> // それぞれの行を個別の <p> タグで表示
        ))}
      </div>

      <p className="sub-highlight">
        あなたに関連のあるトラブルと対策を知りたい方は
      <a
        href="https://lin.ee/zhkQ8DI"
        target="_blank"
        rel="noopener noreferrer"
      >
        <b className="LINE-link">こちら</b>
      </a>
      </p>
    </div>
  );
};

export default PreResult;