import React from "react";
import { useNavigate } from "react-router-dom";
import "./Home.css";
import phoneImage from "../image/phoneImage.png"
import man from "../image/man.png"

function PreHome() {
  const navigate = useNavigate(); 

  const handleLogin = () => {
    navigate("/pre-questionnaire");
  };

  return (
    <div className="home-wrapper">
      <div className="home-content">
        {/* スマホとイラストを重ねるエリア */}
        <div className="phone-section">
          <div className="phone-outer">
            <div className="phone-camera" />
            <div className="phone-screen-frame">
              <img src={phoneImage} alt="スマホ画面" className="phone-screen" />
            </div>
          </div>
          {/* スマホに重ねる人物イラスト */}
          <img src={man} alt="man" className="cover-image" />
        </div>

        {/* テキストエリア */}
        <div className="text-section">
          <div className="speech-bubble">あなたの家族は大丈夫？</div>
          <h1 className="main-title">相続でもめる確率診断</h1>
          <ul className="features">
            <li>専門家監修の無料診断</li>
            <li>5つの質問に答えるだけ</li>
          </ul>
          <button className="consult-button" onClick={handleLogin}>
            診断スタート
          </button>
        </div>
      </div>
    </div>
  );
}

export default PreHome;